budget = 100
tasks = [("small report", 20), ("large report", 90), ("summary", 30), ("index", 40)]
chosen, spent = [], 0
for name, cost in tasks:
    if spent + cost <= budget:
        chosen.append(name); spent += cost; print("chose", name, "cost", cost)
    else:
        print("skipped", name, "cost", cost, "would exceed budget", budget)
print("chosen:", chosen, "spent:", spent, "remaining:", budget - spent)
